<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {homeworkTotals} from '../homework-totals'
import {scheduleApi} from '../schedules'
const props=defineProps<{assignments:any[];classes:any[];classId:number}>()
const emit=defineEmits<{open:[homework:any];'update:classId':[id:number];busy:[value:boolean]}>()
const saving=ref(false),message=ref('')
const totals=(s:any)=>homeworkTotals(Object.values(s.marks).map((m:any)=>m.status))
async function save(s:any,h:any,event:Event){const cell=s.marks[h.id],status=(event.target as HTMLSelectElement).value;if(saving.value)return;const old=cell.status;cell.status=status;saving.value=true;emit('busy',true);error.value='';message.value='';try{const r=await scheduleApi(`teacher/homework/${h.id}/progress`,'PUT',{records:[{student_user_id:s.id,status,version:cell.version}]});Object.assign(cell,r.records[0]);message.value='Saved '+s.full_name+' — '+h.title}catch(e){cell.status=old;error.value=e instanceof Error?e.message:'Unable to save. Refresh before trying again.'}finally{saving.value=false;emit('busy',false)}}
function openDate(date:string){if(onDate(date).length===1)emit('open',onDate(date)[0]);else opened.value=opened.value===date?'':date}
const students=ref<any[]>([]),search=ref(''),error=ref(''),loading=ref(false),opened=ref('')
const dates=computed(()=>[...new Set(props.assignments.map(h=>h.assigned_on))].sort())
const onDate=(date:string)=>props.assignments.filter(h=>h.assigned_on===date).sort((a,b)=>a.id-b.id)
const visible=computed(()=>students.value.filter(s=>(s.full_name+' '+s.login_id).toLowerCase().includes(search.value.trim().toLowerCase())))
async function load(){loading.value=true;error.value='';students.value=[];try{const results=await Promise.all(props.assignments.map(h=>scheduleApi(`teacher/homework/${h.id}/progress`)));const roster=new Map<number,any>();results.forEach((r,i)=>r.students.forEach((s:any)=>{if(!roster.has(s.id))roster.set(s.id,{...s,marks:{}});roster.get(s.id).marks[props.assignments[i]!.id]={status:s.status,version:s.version}}));students.value=[...roster.values()]}catch(e){error.value=e instanceof Error?e.message:'Unable to load homework register.'}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="register"><h2>Homework register</h2><p class="legend">O Done · X Not done · – Late submission · · Unmarked</p><div class="controls"><label>Class<select :value="classId" :disabled="saving||loading" @change="emit('update:classId',Number(($event.target as HTMLSelectElement).value))"><option v-for="c in classes" :key="c.class_id" :value="c.class_id">Grade {{c.grade_label}} · Class {{c.class_name}}</option></select></label><label>Find a student<input v-model="search" type="search" placeholder="Name or student ID"></label><button type="button" class="secondary" :disabled="loading||saving" @click="load">Refresh register</button></div><p v-if="loading" role="status">Loading register…</p><p v-if="message" role="status">{{message}}</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!assignments.length">No homework created for this class yet.</p><p class="formula">Change a mark to save it to the assignment. Done % = (done + late submissions) ÷ total homework. Unmarked work stays in the total. Click a date to open its homework.</p><div v-if="assignments.length" class="scroll" tabindex="0" aria-label="Homework register, scroll for more students and dates"><table><caption>{{visible.length}} students · {{dates.length}} homework dates · Nepal calendar dates</caption><thead><tr><th scope="col">Student</th><th v-for="date in dates" :key="date" scope="col"><div class="date-heading"><button type="button" :aria-expanded="opened===date" :aria-label="date+': '+onDate(date).map(h=>h.title).join(', ')"  :disabled="saving" @click="openDate(date)">{{Number(date.slice(-2))}}<small>{{date.slice(0,7)}}</small></button><div class="date-tip" :class="{shown:opened===date}" role="tooltip"><button v-for="(h,i) in onDate(date)" :key="h.id" type="button" :disabled="saving" @click="emit('open',h)">{{onDate(date).length>1?(i+1)+'. ':''}}{{h.title}}</button></div></div></th><th scope="col">Total homework</th><th scope="col">Done</th><th scope="col">Late</th><th scope="col">Done %</th></tr></thead><tbody><tr v-for="s in visible" :key="s.id"><th scope="row">{{s.full_name}}<small>{{s.login_id}}</small></th><td v-for="date in dates" :key="date"><span class="marks"><label v-for="(h,i) in onDate(date)" :key="h.id" class="mark"><small v-if="onDate(date).length>1">{{i+1}}</small><select v-if="s.marks[h.id]" :value="s.marks[h.id].status" :disabled="saving||loading" :class="s.marks[h.id].status" :aria-label="s.full_name+': '+h.title" :title="h.title" @change="save(s,h,$event)"><option value="pending">·</option><option value="submitted">O</option><option value="missing">X</option><option value="late">–</option><option value="reviewed">O ✓</option></select><span v-else>—</span></label></span></td><td class="total">{{totals(s).total}}</td><td class="total">{{totals(s).done}}</td><td class="total">{{totals(s).late}}</td><td class="total"><strong>{{totals(s).percent===null?'—':totals(s).percent+'%'}}</strong></td></tr></tbody></table></div><p v-if="!loading&&assignments.length&&!visible.length&&!error">No students match.</p><p v-if="dates.some(d=>onDate(d).length>1)" class="help">Numbered marks follow the homework order shown when you open the date. Each assignment keeps its own result.</p></div></template>
<style scoped>
.register{min-width:0;background:white;border:1px solid #d7e3da;border-radius:14px;padding:20px;color:#243e33}.register h2{font-size:20px;margin:0 0 7px}.legend,.help{font-size:12px;color:#6a7e70;line-height:1.6;margin:6px 0}.register .controls{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;align-items:end;gap:10px;margin:16px 0}.register .controls>label{display:flex;flex-direction:column;gap:6px;margin:0;min-width:0;font-size:12px;line-height:18px}.register .controls input,.register .controls select{display:block;width:100%;height:44px;min-height:44px;margin:0;padding:10px;box-sizing:border-box;font:inherit;font-size:16px;line-height:22px;border:1px solid #b9cdbf;border-radius:8px;background:white;color:#243e33}.register .controls>button{width:auto;height:44px;min-height:44px;margin:0;padding:10px 12px;font-size:13px;line-height:22px}.formula{font-size:12px;background:#edf4ef;padding:10px;border-radius:8px;line-height:1.6}.scroll{overflow:auto;max-height:565px;border:1px solid #cad9cf;border-radius:8px;position:relative}table{width:100%;border-collapse:separate;border-spacing:0;font-size:12px}caption{text-align:left;padding:10px;font-size:12px;color:#607869}th,td{min-width:65px;height:36px;padding:0 6px;border-right:1px solid #d5e1d9;border-bottom:1px solid #d5e1d9;text-align:center}thead th{position:sticky;top:0;background:#edf3ef;z-index:2;font-size:11px}tbody th,thead th:first-child{position:sticky;left:0;min-width:160px;width:160px;text-align:left;padding:8px 10px;background:white;z-index:1}thead th:first-child{background:#edf3ef;z-index:3}small{display:block;font-size:10px;color:#748577;margin-top:4px}.date-heading{position:relative}.date-heading>button{width:100%;min-height:44px;margin:0;padding:6px 3px;background:transparent;color:#31583f;font:inherit;font-size:12px}.date-tip{display:none;position:absolute;top:100%;left:0;width:200px;max-width:60vw;padding:8px;background:#243e33;color:white;border-radius:8px;z-index:5;text-align:left;box-shadow:0 4px 14px #0003}.date-tip button{display:block;width:100%;margin:0;padding:8px;background:transparent;color:white;text-align:left;font-size:12px;white-space:normal}.date-heading:hover .date-tip,.date-heading:focus-within .date-tip,.date-tip.shown{display:block}.marks{display:flex;justify-content:center;gap:8px}.mark{margin:0}.mark select{width:44px;height:36px;margin:0;padding:0 2px;border:1px solid #cad9cf;border-radius:5px;background:white;text-align:center;font-size:14px;color:#243e33}.mark select.submitted,.mark select.reviewed{color:#286e44}.mark select.missing{color:#ad3d3d}.mark select.late{color:#9a690b}.total{background:#f6f9f7;padding:5px 10px}button:focus-visible,select:focus-visible{outline:3px solid #4a8660;outline-offset:1px}@media(max-width:650px){.register{padding:12px}.register h2{font-size:18px}.register .controls{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.register .controls>button{grid-column:1/-1;width:100%}tbody th,thead th:first-child{min-width:120px;width:120px;padding:6px}}
</style>
